MM.mnemo[21] = {"cards":[{"id":"ko-k3-0365","w":"생일","cs":"narozeniny","en":"birthday","p":"n","o":"s","ex":"내일 친구 생일인데, 선물을 아직 못 샀어요.","exc":"Zítra má kamarád narozeniny, ale ještě jsem nestihl koupit dárek. (을 → 4. pád)","m":"生 život, narození + 日 den = den narození, tedy narozeniny. Vazba: 생일 축하해요! = Všechno nejlepší k narozeninám!","r":["saeng-生","il-日"]},{"id":"ko-k3-0368","w":"새벽","cs":"úsvit; brzké ráno; časné ranní hodiny","en":"dawn, early morning (새벽 두 시 = 2 a.m.)","p":"n","o":"k","ex":"새벽 두 시인데, 손님이 많아요.","exc":"Jsou dvě hodiny ráno, a přesto je tu spousta zákazníků. (이 → 1. pád)","exa":"새벽 두 시인데, 손님이 많아요. ⚠","m":"Označuje dobu od půlnoci zhruba do východu slunce (새벽 두 시 = dvě hodiny ráno). Časté spojení: 새벽에 일어나다 = vstávat za rozbřesku."},{"id":"ko-k3-0369","w":"전화가 오다","cs":"mít telefonát; někdo volá","en":"to get a phone call","p":"f","o":"m","ex":"어제 자고 있었는데, 한국에서 전화가 왔어요.","exc":"Včera jsem spal, když mi někdo volal z Koreje. (에서 → odkud; 가 → 1. pád)","m":"電 elektřina + 話 řeč = telefon (전화), doslova tedy ‚přichází telefonát‘. Z pohledu příjemce se používá 오다 (přijít), volající naopak hovor ‚posílá‘ nebo ‚dělá‘: 전화를 하다 / 걸다.","r":["jeon-電","hwa-話"]},{"id":"ko-k3-0370","w":"뉴스","cs":"zprávy (v televizi, rádiu)","en":"the news","p":"n","o":"e","ex":"오늘 뉴스에서 봤는데, 그거 진짜예요?","exc":"Dneska jsem to viděl ve zprávách, je to fakt pravda? (에서 → kde)","m":"Výpůjčka z anglického ‚news‘ (zprávy). Častá spojení: 뉴스를 보다 (sledovat zprávy), 뉴스를 듣다 (poslouchat zprávy)."},{"id":"ko-k3-0371","w":"준비","cs":"příprava","en":"preparation","p":"n","o":"s","ex":"준비 많이 했는데(요)…","exc":"Hodně jsem se připravoval, ale…","m":"準 norma + 備 vybavit = vybavit se, jak se má. 준비하다 = připravit.","hada":1,"r":["jun-準","bi-備"]},{"id":"ko-k3-0372","w":"사고 싶다","cs":"chtít koupit","en":"to want to buy","p":"f","o":"k","ex":"이 가방 너무 사고 싶어요.","exc":"Tuhle tašku si strašně moc chci koupit.","m":"Spojení slovesa 사다 (koupit) + vazba -고 싶다 (chtít něco udělat). Pozor na záměnu se slovesem 살다 (žít, bydlet), které má v přítomném čase tvar 살아요."},{"id":"ko-k3-0373","w":"샤워하다","cs":"osprchovat se; sprchovat se","en":"to take a shower","p":"v","o":"e","ex":"샤워하다","exc":"osprchovat se","m":"Výpůjčka z anglického ‚shower‘ (sprcha) + 하다. Častá vazba: 찬물로 샤워하다 = osprchovat se studenou vodou."},{"id":"ko-k3-0374","w":"춤추다","cs":"tancovat; tančit","en":"to dance","p":"v","o":"k","ex":"춤추다","exc":"tancovat","m":"Doslova ‚tančit tanec‘: podstatné jméno 춤 (tanec) + sloveso 추다 (tančit). Často se píše dohromady jako jedno sloveso, nebo s pádem 춤을 추다."}],"gram":{"id":"ko-k3-g21","w":"-는데 / -은데 / -ㄴ데","en":"Linking Verbs (-는데)","cs":"uvedení souvislosti, pozadí děje; ale, zatímco (spojování vět)","vy":"Koncovka -는데 / -(으)ㄴ데 uvádí pozadí situace, vysvětlení před otázkou či návrhem, nebo mírný odpor (‚ale, zatímco‘). U dějových sloves, sloves 있다/없다 a všech minulých tvarů se připojuje -는데. U přídavných jmen se po souhlásce připojuje -은데, po samohlásce nebo ㄹ (které odpadá) -ㄴ데; stejně jako -ㄴ데 se pojí i spona 이다 (인데). Na konci věty s -요 (např. 바쁜데요) zjemňuje výpověď a naznačuje, že mluvčí čeká na reakci.","m":"Pamatuj si rozdělení podle slovního druhu v přítomném čase: dějová slovesa (plus 있다/없다 a minulý čas) berou vždy -는데, zatímco přídavná jména a spona 이다 se řídí stejnými pravidly jako přívlastek -(으)ㄴ (작은데, 예쁜데, 학생인데).","s":[["-는데 · -은데 · -ㄴ데","dějová slovesa / 있다·없다 / minulý čas → -는데 · přídavné jméno + souhláska → -은데 · přídavné jméno + samohláska nebo ㄹ, spona 이다 → -ㄴ데"],["하는데 · 있는데 · 먹는데","dělat · být/mít · jíst + -는데"],["작은데 · 좁은데 · 예쁜데 · 먼데","malý · úzký · hezký · daleký + -(으)ㄴ데"],["내일 일요일인데, 뭐 할 거예요?","Zítra je neděle, co budeš dělat? (uvedení situace → otázka)"],["어제 자고 있었는데, 한국에서 전화가 왔어요.","Včera jsem spal a vtom mi přišel telefonát z Koreje. (pozadí děje → co se stalo)"],["아직 9시인데 벌써 졸려요.","Je teprve devět hodin, ale už se mi chce spát. (protiklad)"],["준비 많이 했는데(요)…","Hodně jsem se připravoval, ale…"],["멋있는데(요)!","Páni, to je ale stylové! (překvapení, obdiv)"],["지금 어디에 있는데(요)?","A kde jsi teď?"],["지금(요)? 지금 바쁜데(요).","Teď? Teď mám zrovna napilno, takže… (očekávání reakce)"],["내일 친구 생일인데, 선물을 아직 못 샀어요.","Zítra má kamarád narozeniny, ale ještě jsem nestihl koupit dárek."],["이거 일본에서 샀는데, 선물이에요.","Tohle jsem koupil v Japonsku a je to dárek pro tebe."],["오늘 뉴스에서 봤는데, 그거 진짜예요?","Dneska jsem to viděl ve zprávách, je to pravda?"],["어? 여기 있었는데.","Cože? Vždyť to tady bylo…"],["영화 재미있었는데, 무서웠어요.","Ten film byl zajímavý, ale strašidelný."],["저 지금 학생인데, 일도 하고 있어요.","Teď jsem student, ale zároveň i pracuju."],["지금 세일하고 있는데, 세일해도 너무 비싸요.","Teď to mají ve slevě, ale i po slevě je to moc drahé."]]}};
